CREATE TABLE fighter_arena (fighter_id TEXT PRIMARY KEY REFERENCES fighters(id), rating INTEGER NOT NULL DEFAULT 1000 CHECK(rating >= 0), wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, draws INTEGER NOT NULL DEFAULT 0, story_cleared INTEGER NOT NULL DEFAULT 0 CHECK(story_cleared BETWEEN 0 AND 100), story_attempts INTEGER NOT NULL DEFAULT 0, ai_style TEXT NOT NULL DEFAULT 'balanced', power REAL NOT NULL DEFAULT 0, next_challenge_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX arena_power ON fighter_arena(power, fighter_id);
CREATE INDEX arena_rating ON fighter_arena(rating DESC, fighter_id);
INSERT INTO fighter_arena(fighter_id) SELECT id FROM fighters;
UPDATE fighter_progression SET payload=json_set(payload, '$.stat_points', COALESCE(json_extract(payload,'$.stat_points'),3), '$.move_points', COALESCE(json_extract(payload,'$.move_points'),0), '$.perk_points', COALESCE(json_extract(payload,'$.perk_points'),0), '$.total_xp', COALESCE(json_extract(payload,'$.total_xp'),0), '$.cap_xp', COALESCE(json_extract(payload,'$.cap_xp'),0));
CREATE TABLE game_operations (account_id TEXT NOT NULL REFERENCES accounts(id), idempotency_key TEXT NOT NULL, kind TEXT NOT NULL, request_hash TEXT NOT NULL, mutation_id TEXT NOT NULL UNIQUE, resource_id TEXT, result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,idempotency_key));
CREATE TABLE online_battles (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE REFERENCES game_operations(mutation_id), mode TEXT NOT NULL CHECK(mode IN ('arena','story','practice')), challenger_account_id TEXT NOT NULL REFERENCES accounts(id), defender_account_id TEXT REFERENCES accounts(id), player_id TEXT NOT NULL REFERENCES fighters(id), rival_id TEXT REFERENCES fighters(id), story_level INTEGER, seed TEXT NOT NULL, engine_version TEXT NOT NULL, catalog_version TEXT NOT NULL, snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), events_json TEXT NOT NULL CHECK(json_valid(events_json)), result_json TEXT NOT NULL CHECK(json_valid(result_json)), summary_json TEXT NOT NULL CHECK(json_valid(summary_json)), created_at INTEGER NOT NULL);
CREATE INDEX battles_challenger ON online_battles(challenger_account_id,created_at DESC,id DESC);
CREATE INDEX battles_defender ON online_battles(defender_account_id,created_at DESC,id DESC);
CREATE INDEX battles_player ON online_battles(player_id,created_at DESC,id DESC);
CREATE INDEX battles_rival ON online_battles(rival_id,created_at DESC,id DESC);
CREATE INDEX battles_account_pair ON online_battles(challenger_account_id,defender_account_id,created_at);
CREATE TRIGGER online_battles_immutable_update BEFORE UPDATE ON online_battles BEGIN SELECT RAISE(ABORT,'BATTLE_IMMUTABLE'); END;
CREATE TRIGGER online_battles_immutable_delete BEFORE DELETE ON online_battles BEGIN SELECT RAISE(ABORT,'BATTLE_IMMUTABLE'); END;
CREATE TABLE progression_events (id TEXT PRIMARY KEY, battle_id TEXT NOT NULL REFERENCES online_battles(id), fighter_id TEXT NOT NULL REFERENCES fighters(id), account_id TEXT NOT NULL REFERENCES accounts(id), side TEXT NOT NULL CHECK(side IN ('player','rival')), xp INTEGER NOT NULL CHECK(xp>=0), rating_delta INTEGER NOT NULL, level_before INTEGER NOT NULL, level_after INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(battle_id,fighter_id));
CREATE INDEX progression_account_day ON progression_events(account_id,side,created_at);
CREATE TABLE offline_activity (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), fighter_id TEXT NOT NULL REFERENCES fighters(id), battle_id TEXT NOT NULL UNIQUE REFERENCES online_battles(id), summary_json TEXT NOT NULL CHECK(json_valid(summary_json)), created_at INTEGER NOT NULL, acknowledged_at INTEGER);
CREATE INDEX offline_unseen ON offline_activity(account_id,acknowledged_at,created_at DESC);
CREATE TABLE game_rate_limits (account_id TEXT NOT NULL REFERENCES accounts(id), window INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(account_id,window));
